-- Upgrade: this registry's own theme, for an install from before it shipped one.
--
-- Such an install holds an unused theme row "NSR Theme" (ea1df455-018f-4ee4-bff5-b0e95a993ea2), copied
-- with the OpenG2P colours, and the registry points at the OpenG2P factory theme.
-- The theme seed inserts only missing rows (so an administrator's edits survive),
-- so it cannot change them. This file does, once, and only while both are still
-- as shipped: the values and the choice of theme are left alone once an
-- administrator has renamed the theme or picked another. Idempotent: after the
-- rename every statement matches nothing; a fresh install matches nothing.

-- 1. The theme's colours and dashboard image.
UPDATE "public"."registry_theme_values"
   SET attribute_value = CASE attribute_name
       WHEN 'primary_color_1' THEN '#3FA7A0'
       WHEN 'primary_color_2' THEN '#0B5563'
       WHEN 'secondary_color_1' THEN '#F2F9F8'
       WHEN 'secondary_color_2' THEN '#E6F4F2'
       WHEN 'secondary_color_3' THEN '#526669'
       WHEN 'neutral_color_1' THEN '#000000'
       WHEN 'neutral_color_2' THEN '#FFFFFF'
       WHEN 'font_url' THEN ''
       WHEN 'font_family' THEN ''
       WHEN 'dashboard_image' THEN 'data:image/svg+xml;base64,'
       ELSE attribute_value END
 WHERE theme_id = 'ea1df455-018f-4ee4-bff5-b0e95a993ea2'
   AND EXISTS (SELECT 1 FROM "public"."registry_themes"
                WHERE theme_id = 'ea1df455-018f-4ee4-bff5-b0e95a993ea2' AND theme_mnemonic = 'NSR Theme');

-- 2. The registry uses it, if it still uses the OpenG2P factory theme.
UPDATE "public"."g2p_registry_configuration"
   SET registry_theme_id = 'ea1df455-018f-4ee4-bff5-b0e95a993ea2'
 WHERE configuration_id = 'c49c0fae-777e-49b2-be3d-b0f1608d19bb'
   AND registry_theme_id = '68721343-ea47-4675-94da-0437d688e9fe'
   AND EXISTS (SELECT 1 FROM "public"."registry_themes"
                WHERE theme_id = 'ea1df455-018f-4ee4-bff5-b0e95a993ea2' AND theme_mnemonic = 'NSR Theme');

-- 3. Its name. Last: steps 1 and 2 key on the old name.
UPDATE "public"."registry_themes"
   SET theme_mnemonic = 'Agents Registry Theme'
 WHERE theme_id = 'ea1df455-018f-4ee4-bff5-b0e95a993ea2' AND theme_mnemonic = 'NSR Theme';
